import{St as e,at as t,it as n,n as r,st as i,vt as a}from"./chunks/framework.BPeR9Rpo.js";var o=JSON.parse(`{"title":"Metamodel packages","description":"","frontmatter":{"title":"Metamodel packages","covers":{"screens":[],"stories":["US-033"]}},"headers":[],"relativePath":"administration/metamodel-packages.md","filePath":"administration/metamodel-packages.md"}`),s={name:`administration/metamodel-packages.md`};function c(r,o,s,c,l,u){let d=e(`Screenshot`);return a(),n(`div`,null,[o[0]||=t(`<h1 id="metamodel-packages" tabindex="-1">Metamodel packages <a class="header-anchor" href="#metamodel-packages" aria-label="Permalink to “Metamodel packages”">​</a></h1><p>A new instance has no entity types. Before anyone can capture entities, you import a metamodel: the shipped starter package or a package of your own.</p><p>Importing packages requires the permission <code>metamodel:write</code>, which only the role <code>metamodel-admin</code> holds – not the local system admin account. Map an IdP group to <code>metamodel-admin</code> (see <a href="./roles-and-permissions">Roles and permissions</a>); as a privileged role, it needs a second factor at the identity provider.</p><h2 id="import-the-starter-configuration" tabindex="-1">Import the starter configuration <a class="header-anchor" href="#import-the-starter-configuration" aria-label="Permalink to “Import the starter configuration”">​</a></h2><p>OEA ships the starter package <code>oea-starter-togaf-classic</code> with the entity types Application Component, Application Service, Data Object, Technology Component, Technology Service, System Software and Network Node, each with the property <em>Status</em>. Version 1.2.0 adds the two system-defined viewpoints <em>Application Landscape</em> and <em>Technology Landscape</em> in ArchiMate (see <a href="#viewpoints-in-packages">Viewpoints in packages</a>). Version 1.1.0 brought German labels for its entity types, <em>Status</em> and its values, and English labels for the values (see <a href="./metamodel-editing#translating-labels">Translating labels</a>). An instance that imported an earlier version receives the labels and viewpoints by importing the package again.</p><p>While the instance has no entity type, the start page shows <em>Import starter configuration</em> to a person with <code>metamodel:write</code>. Choose <em>Import</em> next to the package; the page confirms how many entity types are now available.</p>`,6),i(d,{name:`starter-import`,alt:`Start page with the starter configuration ready for import`}),o[1]||=t('<p>Through the API:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/admin/metamodel/starter-packages&quot;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">                          # list with summary</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/admin/metamodel/starter-packages/oea-starter-togaf-classic/import&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/metatypes&quot;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">                                       # imported entity types</span></span></code></pre></div><h2 id="import-your-own-package" tabindex="-1">Import your own package <a class="header-anchor" href="#import-your-own-package" aria-label="Permalink to “Import your own package”">​</a></h2><p>Packages of your own use the same JSON format (<code>MetamodelPackage</code>, with <code>packageId</code>, <code>packageVersion</code>, <code>publisher</code> and stable UUIDs per element). Import them with <code>POST /admin/metamodel/import</code>:</p><ul><li>A package is imported completely or not at all. Imported content gets the scope <code>imported</code> and the package as origin.</li><li>Importing the same package again updates its own content. Content of another package or of your organization is never overwritten; the answer is <code>409</code> with the problem type <code>urn:oea:problem:package-conflict</code> and the list of conflicts in <code>conflictList</code>, and nothing of the package is stored.</li><li>A package can name a base type for an entity type (<code>baseMetatypeId</code>): an entity type of the same package or a built-in one. Your own properties on its entity types are kept or removed according to the re-import setting (see <a href="./metamodel-editing">Editing the metamodel</a>).</li><li>Packages larger than <code>oea.metamodel.import.max-size</code> (default 10 MB) are rejected with <code>413</code>; faulty JSON or content that does not match the format with <code>422</code> and the location of the problem.</li><li>A package can bring labels per language in <code>i18nBundles</code>, keyed as in <a href="./metamodel-editing#translating-labels">Translating labels</a>, but only for its own elements. A re-import replaces them; your own labels stay.</li><li>The strategy <code>replace</code> and shape assignments are not supported yet (<code>422</code>).</li></ul><p>Every import writes the audit events <code>metamodel.package-imported</code> and <code>metamodel.metatype-imported</code> with one batch ID.</p><h2 id="viewpoints-in-packages" tabindex="-1">Viewpoints in packages <a class="header-anchor" href="#viewpoints-in-packages" aria-label="Permalink to “Viewpoints in packages”">​</a></h2><p>A package can bring viewpoints in <code>viewpoints</code>: each with a stable <code>id</code>, <code>name</code>, optional <code>description</code>, <code>notation</code>, the allowed <code>metatypeIds</code> and <code>connectionTypeIds</code> (types of the package or of the instance) and optional <code>mappings</code>. The import installs them as system-defined, read-only viewpoints with the package as origin (see <a href="./metamodel-editing#viewpoints">Viewpoints</a>).</p><ul><li>A viewpoint has the same limits as one of your own: name up to 255 characters, description up to 1000, at most 500 entity types, 500 connection types and 1000 mappings, sizes 1 to 2000 and colors as <code>#rrggbb</code>. A violation or an unknown type is rejected with <code>422</code> naming the viewpoint.</li><li>Importing the same package again updates its viewpoints, also when one was renamed, and deletes those the package no longer contains. Viewpoints of your organization or of another package are never overwritten: the same ID or name answers <code>409</code>.</li><li>The import result counts the created, updated and deleted viewpoints.</li></ul>',9)])}var l=r(s,[[`render`,c]]);export{o as __pageData,l as default};